// New function to sanitize input
std::string sanitizeInput(const std::string& input) {
    // Simple sanitization: remove any non-alphanumeric characters
    std::string sanitized;
    for (char c : input) {
        if (std::isalnum(c)) {
            sanitized += c;
        }
    }
    return sanitized;
}
